import "../../styles/index-base.css";
import "../../styles/components/kbd.css";
import type { ComponentPropsWithRef } from "react";
import { cn } from "../../lib/cn";

export type KbdProps = ComponentPropsWithRef<"kbd">;

export function Kbd({ className, ...props }: KbdProps) {
  return <kbd className={cn("ix-kbd", className)} {...props} />;
}

export type KbdGroupProps = ComponentPropsWithRef<"span">;

export function KbdGroup({ className, ...props }: KbdGroupProps) {
  return <span className={cn("ix-kbd-group", className)} {...props} />;
}

/* Generated from src/styles.css. Do not edit directly. */

@layer index.tokens, index.base, index.components;

@layer index.components {
.ix-kbd-group { display: inline-flex; align-items: center; gap: 3px; color: var(--ix-fg-muted); font-size: 11px; white-space: nowrap; }

.ix-kbd {
  display: inline-flex;
  min-width: 20px;
  height: 20px;
  align-items: center;
  justify-content: center;
  padding: 0 5px;
  border: 0;
  border-radius: 4px;
  background: var(--ix-bg-subtle);
  box-shadow: inset 0 0 0 1px var(--ix-separator), 0 1px 0 color-mix(in oklch, var(--ix-fg-default) 8%, transparent);
  color: var(--ix-fg-muted);
  font-family: var(--ix-font-code);
  font-size: 10.5px;
  font-weight: 500;
  line-height: 1;
  white-space: nowrap;
}
}
